400       .in_i ({$bits(ibex_mubi_t){ctrl_busy, if_busy, lsu_busy}}),
401       .out_o(busy_bits_buf)
402     );
403 
404     // Set core_busy_o to IbexMuBiOn if even a single input is high.
405     for (genvar i = 0; i < $bits(ibex_mubi_t); i++) begin : g_core_busy_bits
406       if (IbexMuBiOn[i] == 1'b1) begin : g_pos
407         assign core_busy_o[i] =  |busy_bits_buf[i*NumBusySignals +: NumBusySignals];
408       end else begin : g_neg
409         assign core_busy_o[i] = ~|busy_bits_buf[i*NumBusySignals +: NumBusySignals];
410       end
411     end
412   end else begin : g_core_busy_non_secure
413     // For non secure Ibex, synthesis is allowed to optimize core_busy_o.
414     assign core_busy_o = (ctrl_busy || if_busy || lsu_busy) ? IbexMuBiOn : IbexMuBiOff;
